/**
 * Meeting codes: an eight-character alias for a room's full invitation link,
 * held by the code service at `/codes` (see docs/meeting-codes.md).
 *
 * The code is generated by the service. This module only canonicalises what
 * a person types, presents a code in triples, and speaks the service's HTTP
 * contract. The format is foregather `foregather-access/base32-en-v1/1` at a
 * fixed eight characters, parsed exactly as foregather-kit's
 * `canonical_characters` does: case and surrounding ASCII whitespace are
 * normalised, hyphens are allowed only between triples, and nothing is
 * substituted for an ambiguous character.
 *
 * The delete token is a host secret. It is kept in this device's store next
 * to the room's other host records, never in a link, a bookmark or anything
 * synced to another member.
 */
import type { DeviceStore } from './device-store.js'

export const MEETING_CODE_ALPHABET = '0123456789ABCDEFGHJKMNPQRSTVWXYZ'
export const MEETING_CODE_LENGTH = 8
/** The most the service accepts: seven days from issue. */
export const MEETING_CODE_MAX_SECONDS = 7 * 24 * 3600
/** Asked for a minute short of that, so a clock a little ahead is not refused. */
export const MEETING_CODE_SKEW_SECONDS = 60
export const SHORT_LINK_BASE = 'https://kithmoot.app/c/'

const ASCII_WHITESPACE = /^[\t\n\f\r ]+|[\t\n\f\r ]+$/g

/** The canonical form (eight uppercase symbols, no hyphens), or undefined. */
export function parseMeetingCode(value: string): string | undefined {
  if (value.length > 64 || !/^[\x00-\x7f]*$/.test(value)) return undefined
  const text = value.replace(ASCII_WHITESPACE, '').toUpperCase()
  if (text.includes('-')) {
    const groups = text.split('-')
    for (let i = 0; i < groups.length; i++) {
      const group = groups[i]!
      if (group.length === 0 || group.length > 3 || (i < groups.length - 1 && group.length !== 3)) return undefined
    }
  }
  const code = text.replaceAll('-', '')
  if (code.length !== MEETING_CODE_LENGTH) return undefined
  for (const c of code) if (!MEETING_CODE_ALPHABET.includes(c)) return undefined
  return code
}

/** `ABCDEFGH` as `ABC-DEF-GH`, for reading out and copying. */
export function displayMeetingCode(code: string): string {
  const canonical = parseMeetingCode(code)
  if (!canonical) throw new Error('not a meeting code')
  return `${canonical.slice(0, 3)}-${canonical.slice(3, 6)}-${canonical.slice(6)}`
}

/** The short link a code opens: the canonical form, which is what URLs carry. */
export function meetingCodeLink(code: string): string {
  const canonical = parseMeetingCode(code)
  if (!canonical) throw new Error('not a meeting code')
  return SHORT_LINK_BASE + canonical
}

/**
 * Whether a room may offer a code: an Ask room, or one with an end. The
 * caller has already checked that this browser is the room's creator.
 */
export function meetingCodeEligible(room: { endsAt?: number; ask: boolean; now: number }): boolean {
  if (room.endsAt !== undefined) return room.endsAt > room.now
  return room.ask
}

/** The `expires` to ask for: the room's end or seven days less a minute,
 *  whichever is sooner. Never past the room's end. When it runs out the host
 *  issues a new code from the same control. */
export function meetingCodeExpiry(endsAt: number | undefined, now: number): number {
  const cap = now + MEETING_CODE_MAX_SECONDS - MEETING_CODE_SKEW_SECONDS
  return endsAt === undefined ? cap : Math.min(endsAt, cap)
}

export const MEETING_ENDED = 'This meeting has ended'
export const MEETING_CODE_UNKNOWN = 'We could not find that code. Check it and try again'
export const MEETING_CODE_TOO_MANY = 'Too many tries. Wait a minute'
export const MEETING_CODES_UNAVAILABLE = 'Meeting codes are unavailable right now. Share the full link instead.'

/** A refusal the service answered, with the words to show for it. */
export class MeetingCodeError extends Error {
  constructor(message: string, readonly status: number) { super(message); this.name = 'MeetingCodeError' }
}
/** No answer at all: the person is offered Retry. */
export class MeetingCodeNetworkError extends Error {
  constructor() { super('The meeting code service could not be reached.'); this.name = 'MeetingCodeNetworkError' }
}

export interface IssuedMeetingCode { code: string; expires: number; deleteToken: string }

type Fetch = (input: string, init?: RequestInit) => Promise<Response>

export interface MeetingCodeClient {
  create(link: string, expires: number): Promise<IssuedMeetingCode>
  resolve(code: string): Promise<{ link: string; expires: number }>
  /** True once the code is gone (deleted, already ended or unknown). */
  remove(code: string, deleteToken: string): Promise<boolean>
}

export function meetingCodeClient({ base = '/codes', fetch: send = globalThis.fetch.bind(globalThis) }: { base?: string; fetch?: Fetch } = {}): MeetingCodeClient {
  const root = base.replace(/\/+$/, '')
  async function call(path: string, init: RequestInit): Promise<Response> {
    try { return await send(root + path, { cache: 'no-store', credentials: 'omit', ...init }) }
    catch { throw new MeetingCodeNetworkError() }
  }
  return {
    async create(link, expires) {
      const response = await call('', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ link, expires }) })
      if (response.status === 429) throw new MeetingCodeError(MEETING_CODE_TOO_MANY, 429)
      // The store or the service-wide daily cap is full.
      if (response.status === 503) throw new MeetingCodeError(MEETING_CODES_UNAVAILABLE, 503)
      if (response.status !== 201) throw new MeetingCodeError('A meeting code could not be made for this room. Share the link instead.', response.status)
      const body = await response.json().catch(() => undefined) as Partial<IssuedMeetingCode> | undefined
      const code = typeof body?.code === 'string' ? parseMeetingCode(body.code) : undefined
      if (!code || typeof body?.deleteToken !== 'string' || !body.deleteToken || !Number.isSafeInteger(body.expires)) {
        throw new MeetingCodeError('The meeting code service gave an answer this app does not understand.', response.status)
      }
      return { code, expires: body.expires!, deleteToken: body.deleteToken }
    },
    async resolve(value) {
      const code = parseMeetingCode(value)
      if (!code) throw new MeetingCodeError(MEETING_CODE_UNKNOWN, 0)
      const response = await call(`/${code}`, { method: 'GET' })
      if (response.status === 410) throw new MeetingCodeError(MEETING_ENDED, 410)
      if (response.status === 404) throw new MeetingCodeError(MEETING_CODE_UNKNOWN, 404)
      if (response.status === 429) throw new MeetingCodeError(MEETING_CODE_TOO_MANY, 429)
      if (response.status !== 200) throw new MeetingCodeNetworkError()
      const body = await response.json().catch(() => undefined) as { link?: unknown; expires?: unknown } | undefined
      if (typeof body?.link !== 'string' || typeof body.expires !== 'number') throw new MeetingCodeNetworkError()
      return { link: body.link, expires: body.expires }
    },
    async remove(code, deleteToken) {
      const response = await call(`/${code}`, { method: 'DELETE', headers: { Authorization: `Bearer ${deleteToken}` } })
      return response.status === 204 || response.status === 404 || response.status === 410
    },
  }
}

/**
 * The link a code returned, as an address in this app: only a KithMoot join
 * link (`/j/` on one of the two KithMoot origins, with an invitation in its
 * fragment and nothing else) is accepted. The caller re-bases the fragment
 * onto its own join page, as pasting an invite link does.
 */
export function returnedJoinFragment(link: string): string | undefined {
  let url: URL
  try { url = new URL(link) } catch { return undefined }
  if (url.protocol !== 'https:' || url.username || url.password || url.search) return undefined
  if (url.host !== 'kithmoot.forgesworn.dev' && url.host !== 'kithmoot.app') return undefined
  if (url.pathname !== '/j/' || url.hash.length <= 1) return undefined
  return url.hash
}

// ---------------------------------------------------------------------------
// The host's records: one per invitation, and a queue of codes still to
// delete. Both in the device store, beside the invitation owner record.
// ---------------------------------------------------------------------------

export const MEETING_CODE_PREFIX = 'kithmoot.meeting-code.v1.'
export const MEETING_CODE_RETIRE_KEY = 'kithmoot.meeting-code-retire.v1'

export interface StoredMeetingCode extends IssuedMeetingCode { roomId: string }

export function storeMeetingCode(store: DeviceStore, invitationId: string, record: StoredMeetingCode): void {
  store.set(MEETING_CODE_PREFIX + invitationId, JSON.stringify(record))
}

function readRecord(raw: string | null): StoredMeetingCode | undefined {
  if (!raw) return undefined
  try {
    const value = JSON.parse(raw) as Partial<StoredMeetingCode>
    const code = typeof value.code === 'string' ? parseMeetingCode(value.code) : undefined
    if (!code || typeof value.deleteToken !== 'string' || typeof value.roomId !== 'string' || !Number.isSafeInteger(value.expires)) return undefined
    return { code, deleteToken: value.deleteToken, roomId: value.roomId, expires: value.expires! }
  } catch { return undefined }
}

/** The live code for this invitation, if one was issued here and has not expired. */
export function loadMeetingCode(store: DeviceStore, invitationId: string, now: number): StoredMeetingCode | undefined {
  const record = readRecord(store.get(MEETING_CODE_PREFIX + invitationId))
  if (record && record.expires <= now) { store.remove(MEETING_CODE_PREFIX + invitationId); return undefined }
  return record
}

/** Move this invitation's code, or every code for a room, onto the delete
 *  queue and drop the record. Returns what was queued. */
export function retireMeetingCodes(store: DeviceStore, match: { invitationId?: string; roomId?: string }, now: number): StoredMeetingCode[] {
  const retired: StoredMeetingCode[] = []
  for (const key of store.keys()) {
    if (!key.startsWith(MEETING_CODE_PREFIX)) continue
    const record = readRecord(store.get(key))
    const hit = match.invitationId !== undefined ? key === MEETING_CODE_PREFIX + match.invitationId : record?.roomId === match.roomId
    if (!hit) continue
    store.remove(key)
    // An expired code needs no client: the service has already ended it.
    if (record && record.expires > now) retired.push(record)
  }
  if (retired.length) {
    const queue = pendingRetirements(store, now)
    for (const record of retired) if (!queue.some(q => q.code === record.code)) queue.push(record)
    writeQueue(store, queue)
  }
  return retired
}

export function pendingRetirements(store: DeviceStore, now: number): StoredMeetingCode[] {
  try {
    const value = JSON.parse(store.get(MEETING_CODE_RETIRE_KEY) ?? '[]') as unknown
    if (!Array.isArray(value)) return []
    return value.map(v => readRecord(JSON.stringify(v))).filter((r): r is StoredMeetingCode => r !== undefined && r.expires > now)
  } catch { return [] }
}

function writeQueue(store: DeviceStore, queue: StoredMeetingCode[]): void {
  if (queue.length) store.set(MEETING_CODE_RETIRE_KEY, JSON.stringify(queue))
  else store.remove(MEETING_CODE_RETIRE_KEY)
}

/** Send every queued DELETE. A code the service confirms gone leaves the
 *  queue; a failure stays for the next open, and never throws. */
export async function drainRetirements(store: DeviceStore, client: MeetingCodeClient, now: number): Promise<void> {
  const queue = pendingRetirements(store, now)
  if (!queue.length) { writeQueue(store, []); return }
  const left: StoredMeetingCode[] = []
  for (const record of queue) {
    const gone = await client.remove(record.code, record.deleteToken).catch(() => false)
    if (!gone) left.push(record)
  }
  // Another retirement may have joined the queue while these were sent.
  const latest = pendingRetirements(store, now).filter(r => !queue.some(q => q.code === r.code))
  writeQueue(store, [...left, ...latest])
}
